#!/usr/bin/env bash\n# Script to create a bucket in MinIO (invoked in container or via mc)\n# Usage: ./infra/init_minio.sh\nset -e\n\nif ! command -v mc &> /dev/null; then\n  echo "mc (MinIO client) not found. Attempting to use dockerized mc..."\nfi\n\n# Attempt to create bucket using dockerized mc against local minio\necho "Creating bucket dataspace-transfers on MinIO (http://localhost:9000)..."\ndocker run --rm --network host minio/mc:latest alias set myminio http://127.0.0.1:9000 minioadmin minioadmin123 || true\ndocker run --rm --network host minio/mc:latest mb myminio/dataspace-transfers || true\necho "Bucket dataspace-transfers created or already exists."